begin;
set local search_path=public,extensions;
select plan(41);

select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=pg_catalog%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('begin_catalog_import','stage_catalog_import_rows','validate_catalog_import','commit_catalog_import','get_catalog_import_report')),'all five import RPCs are SECURITY DEFINER with fixed search paths');
select ok(not exists(select 1 from (values('public.catalog_source_files'),('public.catalog_import_chunks'),('public.catalog_import_chunk_rows'))t(name) cross join(values('anon'),('authenticated'),('service_role'))r(role) where has_table_privilege(r.role,t.name,'SELECT,INSERT,UPDATE,DELETE')),'source, chunk and row-link evidence tables expose no direct runtime privilege');
select ok((select count(*)=5 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('begin_catalog_import','stage_catalog_import_rows','validate_catalog_import','commit_catalog_import','get_catalog_import_report')),'all import RPC signatures are authenticated-only');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in('catalog_baseline_uuid','catalog_baseline_slug','catalog_canonical_json','catalog_import_payload_error','assert_catalog_baseline_actor','catalog_import_actual_counts') and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('authenticated',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'private import helpers are inaccessible to runtime roles');

