('f3000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','baseline-other@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code) values('f3000000-0000-0000-0000-000000000001','MATRICIA_ADMIN'),('f3000000-0000-0000-0000-000000000002','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by) values
('f3010000-0000-0000-0000-000000000001','Baseline Test Steward','Baseline Test','ACTIVE','f3000000-0000-0000-0000-000000000001'),
('f3010000-0000-0000-0000-000000000002','Other Baseline Steward','Other Baseline','ACTIVE','f3000000-0000-0000-0000-000000000002');

create temporary table p06_import_fixture(manifest jsonb,expected jsonb,sources jsonb,bundle_hash text,batch_id uuid,begin_response jsonb,validate_response jsonb,commit_expected integer,commit_response jsonb);
create temporary table p06_import_errors(test_key text primary key,sqlstate text,message text);
grant select,update on p06_import_fixture to authenticated;
grant select,insert on p06_import_errors to authenticated;
grant usage on schema extensions to authenticated;
grant execute on function extensions.is(anyelement,anyelement,text),extensions.ok(boolean,text) to authenticated;
insert into p06_import_fixture(manifest,expected,sources,bundle_hash) values(
 jsonb_build_object('catalog_version','1.0.0','counts',jsonb_build_object('libraries',10,'categories',40,'subcategories',80,'services',200,'service_subcategory_links',212,'rfq_questions',5000,'diagnostic_questions',700,'provider_questions',300,'total_questions',6000),'by_library',jsonb_build_object('TST',jsonb_build_object('categories',4,'subcategories',8,'services',20,'rfq_questions',500,'diagnostic_questions',70,'provider_questions',30))),
 jsonb_build_object('libraries',1,'categories',4,'subcategories',8,'services',20,'service_subcategory_links',20,'rfq_questions',500,'diagnostic_questions',70,'provider_questions',30,'total_questions',600),
 (select jsonb_agg(jsonb_build_object('path','catalogue/Matricia_Catalogue_Metier_V1/'||name,'sha256',repeat(substr(md5(name),1,1),64),'byte_size',100,'data_rows',rows,'generator_version','1.0.0')) from(values('catalog_manifest.json',1),('libraries.csv',10),('categories.csv',40),('subcategories.csv',80),('services.csv',200),('service_subcategory_links.csv',212),('questions_rfq.csv',5000),('questions_diagnostic.csv',700),('questions_provider_qualification.csv',300),('questions_all.jsonl',6000))s(name,rows)),repeat('f',64));
update p06_import_fixture f set bundle_hash=encode(extensions.digest(convert_to(private.catalog_canonical_json(jsonb_build_object('manifest',f.manifest,'sources',(select jsonb_agg(jsonb_build_object('path',s->>'path','sha256',s->>'sha256','byte_size',(s->>'byte_size')::bigint,'data_rows',(s->>'data_rows')::integer)order by s->>'path')from jsonb_array_elements(f.sources)s))),'UTF8'),'sha256'),'hex');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
do $runtime$begin perform public.begin_catalog_import('MATRICIA_GOLD_MASTER_BASELINE_TEST:NO_AAL',repeat('e',64),f.manifest,'TST','f3010000-0000-0000-0000-000000000001',f.expected,f.sources,'baseline-no-aal') from p06_import_fixture f;exception when others then insert into p06_import_errors values('no-aal',sqlstate,sqlerrm);end$runtime$;
reset role;
select is((select sqlstate||':'||message from p06_import_errors where test_key='no-aal'),'42501:CATALOG_IMPORT_DENIED'::text,'missing AAL claim fails closed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok($$select public.begin_catalog_import('MATRICIA_GOLD_MASTER_BASELINE_TEST:BAD_ALLOWLIST',f.bundle_hash,f.manifest,'TST','f3010000-0000-0000-0000-000000000001',f.expected,f.sources-0,'baseline-bad-allowlist')from p06_import_fixture f$$,'22023'::char(5),'INVALID_CATALOG_IMPORT_REQUEST','begin rejects an incomplete source allowlist');
select extensions.throws_ok($$select public.begin_catalog_import('MATRICIA_GOLD_MASTER_BASELINE_TEST:BAD_BUNDLE',repeat('0',64),f.manifest,'TST','f3010000-0000-0000-0000-000000000001',f.expected,f.sources,'baseline-bad-bundle')from p06_import_fixture f$$,'22000'::char(5),'CATALOG_BUNDLE_HASH_MISMATCH','begin rejects a bundle hash not recomputed from canonical sources and manifest');
