do $runtime$begin perform public.begin_catalog_import('MATRICIA_GOLD_MASTER_BASELINE_TEST:TST',f.bundle_hash,f.manifest,'TST','f3010000-0000-0000-0000-000000000001',f.expected,f.sources,'baseline-test-begin','f3020000-0000-0000-0000-000000000001') from p06_import_fixture f;exception when others then insert into p06_import_errors values('begin-replay-scope',sqlstate,sqlerrm);end$runtime$;
