select public.stage_catalog_import_rows(batch_id,'catalogue/Matricia_Catalogue_Metier_V1/subcategories.csv','SUBCATEGORY',(select jsonb_agg(jsonb_build_object('line_number',n+1,'business_key','TST-SUB-'||n,'payload',jsonb_build_object('library_code','TST','macro_category_code','TST-MACRO-'||ceil(n/2.0)::integer,'code','TST-SUB-'||n,'name_fr','Sous-catégorie '||n,'description_fr','Description sous-catégorie '||n,'order',n,'status','ACTIVE','version',1,'franchisee_can_edit',true)))from generate_series(1,8)n),'stage-subcategories') from p06_import_fixture;
