select public.stage_catalog_import_rows(batch_id,'catalogue/Matricia_Catalogue_Metier_V1/questions_all.jsonl','QUESTION',(select jsonb_agg(jsonb_build_object('line_number',n,'business_key','Q-RFQ-TST-'||n,'payload',jsonb_build_object('library_code','TST','category_code','TST-SUB-'||((((ceil(n/25.0)::integer)-1)%8)+1),'service_code','TST-SVC-'||ceil(n/25.0)::integer,'phase','RFQ','section','Cadrage','order',((n-1)%25)+1,'label_fr','Question RFQ '||n,'help_fr','Aide RFQ','answer_type','LONG_TEXT','required',true,'required_for_quote',true,'options','[]'::jsonb,'validation_schema','{}'::jsonb,'condition','{}'::jsonb,'data_key','rfq.tst.'||n,'weight',1,'max_score',10,'sensitivity','BUSINESS','template_key','RFQ_BASE'))order by n)from generate_series(1,200)n),'stage-questions-1') from p06_import_fixture;
